import type { Claim } from '../claims/claims';

// A claim's due-by: fixed when it was created, from the terms of its person's grade in force on its date.
export function ClaimDueBy({ claim }: { claim: Claim }) {
  return <span data-testid="claim-due-by">{claim.dueBy}</span>;
}
import type { Claim } from '../claims/claims';
import { useSheetToday } from '../session/sheetToday';
import { overdue } from './overdue';

// Whether a claim is overdue: OPEN (or PENDING), with its due-by before the sheet's today.
export function ClaimOverdue({ claim }: { claim: Claim }) {
  const today = useSheetToday();
  return <span data-testid="claim-overdue">{overdue(claim, today) ? 'yes' : 'no'}</span>;
}
import { isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';

/** Whether a claim is overdue: it is OPEN (or PENDING) and its due-by, fixed when it was created, is before the sheet's today. */
export function overdue(claim: Claim, today: string): boolean {
  return isOpen(claim) && today !== '' && claim.dueBy < today;
}

/** How many full 30-day periods a claim is overdue on the sheet's today: 0 unless it is overdue. */
export function latePeriods(claim: Claim, today: string): number {
  if (!overdue(claim, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${claim.dueBy}T00:00:00Z`)) / 86_400_000;
  return Math.floor(Math.round(days) / 30);
}
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { ClaimDueBy } from './ClaimDueBy';
import { ClaimOverdue } from './ClaimOverdue';
import { OverdueTotals } from './OverdueTotals';
import { PersonOverdueCount, PersonOverdueTotal } from './PersonOverdue';

export const contributions = [
  PersonColumnHeads.fill({ order: 16, Component: () => <th>Overdue</th> }),
  PersonColumns.fill({ order: 16, Component: PersonOverdueCount }),
  PersonColumnHeads.fill({ order: 17, Component: () => <th>Overdue total</th> }),
  PersonColumns.fill({ order: 17, Component: PersonOverdueTotal }),
  ClaimRowValues.fill({ order: 12, Component: ClaimDueBy }),
  ClaimRowValues.fill({ order: 13, Component: ClaimOverdue }),
  HomeMain.fill({ order: 45, Component: OverdueTotals }),
];
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { total, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';
import { personOverdue } from './overdue';

// The sheet's overdue count and overdue-total: everyone's added up.
export function OverdueTotals() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const each = people.map((p) =>
    personOverdue(claims.filter((c) => c.personId === p.id), rates, p.grades, p.holds, rules),
  );
  return (
    <p>
      Overdue: <strong data-testid="rollup-overdue-count">{each.reduce((n, o) => n + o.count, 0)}</strong>, totalling{' '}
      <strong data-testid="rollup-overdue-total">{total(each.map((o) => o.total))}</strong>
    </p>
  );
}
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, total } from '../rates/rates';
import type { Rate } from '../rates/rates';
import type { GradeFrom, Hold } from '../people/people';
import type { DueRules } from '../settings/settings';
import { overdue } from './dueBy';

export { overdue } from './dueBy';

/**
 * A person's overdue claims that count (none of their open ones a hold covers): how many, and
 * their dues (late charges included) added up (skipping n/a).
 */
export function personOverdue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): { count: number; total: string } {
  const late = claims.filter((c) => counts(c, holds) && overdue(c, rules.today));
  return { count: late.length, total: total(late.map((c) => claimDue(c, rates, grades, rules))) };
}
import { useClaims } from '../claims/claims';
import type { Person } from '../people/people';
import { useRates } from '../rates/rates';
import { useDueRules } from '../settings/settings';
import { personOverdue } from './overdue';

function usePersonOverdue(person: Person) {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return personOverdue(claims, rates, person.grades, person.holds, rules);
}

// How many of a person's counting claims are overdue.
export function PersonOverdueCount({ person }: { person: Person }) {
  return <td data-testid="person-overdue-count">{usePersonOverdue(person).count}</td>;
}

// The dues (late charges included) of a person's overdue counting claims, added up.
export function PersonOverdueTotal({ person }: { person: Person }) {
  return <td data-testid="person-overdue-total">{usePersonOverdue(person).total}</td>;
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;

/**
 * A claim a person has on a sheet. {@code id} is null until the claim is first saved; {@code number}
 * is null unless the claim has been opened (a draft has none; a voided claim keeps it). {@code due} is the
 * due fixed when the claim was settled, or null while it is live (not settled, or settled with no rate).
 * {@code openedBy} is the user who opened the claim, or null while it is a draft. {@code stated} is whether
 * its person's last statement bound it to a figure, {@code statedDue} (null: n/a) — it then shows and totals
 * that figure, not its live one. {@code number} is sheet-wide (1, 2, ...) or, under period numbering,
 * within its period (P1-1, X-1). {@code corrects} is, for a correction, the number of the claim it corrects (null:
 * not a correction). {@code dueBy} is fixed when the claim is created: its date plus the terms of its person's
 * grade in force on that date; it does not change when the terms or its date change later. While PENDING the claim is not bound: it shows and totals its live figure, and is bound again
 * once rejected (back to OPEN) when the statement included it.
 */
public record Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
        String corrects, LocalDate dueBy) {

    /** The same claim with another status, number, fixed due and opener. */
    public Claim withStatus(ClaimStatus next, String nextNumber, BigDecimal nextDue, String nextOpenedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, next, nextNumber, nextDue, nextOpenedBy, stated,
                statedDue, corrects, dueBy);
    }

    /** Whether the claim is a correction: a negative amount naming the settled claim it corrects. */
    public boolean correction() {
        return corrects != null;
    }

    /** Whether the claim counts toward the totals: only OPEN, PENDING and SETTLED claims do. */
    public boolean counts() {
        return status.open() || status == ClaimStatus.SETTLED;
    }

    /** Whether the claim counts toward the live totals when a hold on its person covers it or not: a held open (or pending) claim does not. */
    public boolean counts(boolean held) {
        return status == ClaimStatus.SETTLED || (status.open() && !held);
    }

    /** Whether a statement binds the claim now: it was stated and is not PENDING. */
    public boolean bound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /** Whether the claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
    public boolean keepsFigure() {
        return due != null || (bound() && statedDue != null);
    }

    /**
     * The claim's figure (null: n/a): the due fixed when it was settled, else the figure its statement bound
     * it to (not while PENDING), else its amount at the given live rate (null: none), at least the sheet's floor — a correction has
     * no floor. Its live figure rounds by the sheet's policy date.
     */
    public BigDecimal figure(BigDecimal liveRate, BigDecimal floor, Rounding rounding) {
        if (due != null) {
            return due;
        }
        if (bound()) {
            return statedDue;
        }
        RoundingMode mode = rounding.modeFor(this);
        return correction() ? due(amount, liveRate, mode) : due(amount, liveRate, floor, mode);
    }

    /**
     * The claim's due (null: n/a): its {@link #figure figure}, plus the late charge on it while it is overdue. A
     * settled claim's fixed due already has the charge frozen in.
     */
    public BigDecimal due(BigDecimal liveRate, BigDecimal floor, LateCharge late, Rounding rounding) {
        BigDecimal figure = figure(liveRate, floor, rounding);
        return due != null || figure == null ? figure : figure.add(late.on(this, figure, rounding.modeFor(this)));
    }

    /** An amount times a percent rate, divided by 100, rounded by the mode to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate, RoundingMode mode) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, mode);
    }

    /** A live due: {@link #due(BigDecimal, BigDecimal, RoundingMode)}, raised to the floor; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate, BigDecimal floor, RoundingMode mode) {
        BigDecimal due = due(amount, rate, mode);
        return due == null || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
    }

    /** The audit field for the claim's number, " number=<n>", or "" when it has none. */
    public static String auditNumber(String number) {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * A claim's due as the screen shows it at this moment (null: n/a): its fixed due, else its figure at its person's
 * grade's rate in force on its date, raised to the sheet's floor and rounded by its policy date — or the figure a
 * statement bound it to — plus the late charge it has on the sheet's today, if overdue.
 */
public final class ClaimDueNow {

    private ClaimDueNow() {
    }

    public static BigDecimal of(Claim claim, SheetRepository sheets, PersonRepository people, RateRepository rates,
            SettingRepository settings, ClaimRepository claims) {
        Person person = people.find(claim.sheetId(), claim.personId());
        BigDecimal rate = person == null ? null
                : Rate.inForce(rates.findAll(claim.sheetId()), person.gradeOn(claim.date()), claim.date());
        LocalDate today = sheets.today(claim.sheetId());
        return claim.due(rate, settings.floor(claim.sheetId()), settings.lateCharge(claim.sheetId(), today),
                settings.rounding(claim.sheetId(), today, claims.findForPerson(claim.sheetId(), claim.personId())));
    }
}

